      const { sha: remotoSha, base } = rotear(h, { version: '2.0.0' });
      h.route(`${base}audio/01.mp3`, { throws: 'rede caiu no meio' });   // o download do resolvido FALHA
      const pack = mkPack(h, { version: '2.0.0', sha: remotoSha });
