      const mutIgnoraSha = (s) => s.replace(
        '    const anchored = insp.actualSha != null && insp.actualSha === markerSha && insp.actualSha === resolved.manifestSha256;',
        '    const anchored = true;');
      const c = cenarioCoincidenteNaoReady();
      const rOrig = await c.run();
