    check('LP2.1 G1-C/5 (o corretivo não destrói 1.0.0): a versão anterior segue em disco (GC de versões superadas está FORA de escopo)',
      C.arqAntigo > 0 && C.arq2 > 0, `antigo=${C.arqAntigo} arq2=${C.arq2}`);

