    const E = await resetRealG1();
    check('LP2.1 G1-E/1-2 (Reset revoga TODOS os voos anteriores): nem A nem B publicam',
      E.rA.ok === false && E.rA.reason === 'reset' && E.rB.ok === false && E.rB.reason === 'reset',
      `A=${E.rA.reason} B=${E.rB && E.rB.reason}`);
